/*
 * component: swc_eGas
 * cycletime: 0
 * description: Runnable
 * events: ev_joystick_onData
 * name: EGAS_control_run
 * shortname: control
 * signalIN: so_joystick
 * signalOUT: so_targetSpeed
 * task: tsk_control
 */
void EGAS_control_run(RTE_event ev, uint32_t cycleTime){
	
	/* USER CODE START EGAS_control_run */

	//Note: 
	//The parameters identify the activation source, which can either be an event (onData, onError) 
	//or a cyclic activation. One of the values will be 0, idicating that this event has not been fired.
	//The other must have a none 0 value.
	
    //INPUT
    //Measure cyclic time of runnable
    Run2_Write(1);
    WD_Alive(1);
    
    SC_JOYSTICK_data_t  joystick        = SC_JOYSTICK_INIT_DATA;
    SC_SPEED_data_t     targetSpeed     = SC_SPEED_INIT_DATA;
    SC_ENABLE_data_t    breakSignal    = SC_ENABLE_INIT_DATA;
    
    //Since this runnable is called on value update error handling is not required here
    joystick = RTE_SC_JOYSTICK_get(&SO_JOYSTICK_signal);
    
    
    //Read the breakbutton here.
    RTE_SC_ENABLE_pullPort(&SO_BREAK_signal);
    breakSignal = RTE_SC_ENABLE_get(&SO_BREAK_signal);
    
    //LOGIC
    
     //at 0 position the joystick is giving -4 so adding a margin of +-2
    if(joystick.x >= -6 && joystick.x <= -2){
        targetSpeed.speed = 0;
        targetSpeed.direction = 0;
    }
    
    //Forward
    else if(joystick.x > -2){
        targetSpeed.speed     = ((uint16_t)joystick.x * MAX_RPM) / JOYSTICK_MAX;  // 0..MAX_RPM
        targetSpeed.direction = 1;
    }
    
    //Reverse
    else if(joystick.x < -6) {
        targetSpeed.speed     = ((uint16_t)(-joystick.x) * MAX_RPM) / JOYSTICK_MAX;  // 0..MAX_RPM
        targetSpeed.direction = -1;
    }
    
    //OUTPUT
    RTE_SC_ENABLE_set(&SO_BREAK_signal, breakSignal);
    RTE_SC_SPEED_set(&SO_TARGETSPEED_signal, targetSpeed);

    
    //Measure cyclic time of runnable
    Run2_Write(0);
    CancelAlarm(Alarm_io);
    

    /* USER CODE END EGAS_control_run */
}

/*
 * component: swc_eGas
 * cycletime: 100
 * description: Engine controller PWM runnable
 * events: 
 * name: EGAS_controlEngine_run
 * shortname: controlEngine
 * signalIN: so_targetSpeed|so_currentSpeed
 * signalOUT: so_targetSpeed|so_currentSpeed|so_controlSpeed
 * task: tsk_io
 */
void EGAS_controlEngine_run(RTE_event ev, uint32_t cycleTime){
	
	/* USER CODE START EGAS_controlEngine_run */

	//Note: 
	//The parameters identify the activation source, which can either be an event (onData, onError) 
	//or a cyclic activation. One of the values will be 0, idicating that this event has not been fired.
	//The other must have a none 0 value.
    
    
    //INPUT
    //Measure cyclic time of runnable
    Run3_Write(1);
    WD_Alive(2);
    
    SC_SPEED_data_t targetSpeed     = SC_SPEED_INIT_DATA;
    uint32_t allowedSignalAge = 500;    //Modify this based on the developer requirement
    
    //Since this runnable is called on even
    if(RTE_SC_SPEED_getAge(&SO_TARGETSPEED_signal) > allowedSignalAge){
        targetSpeed.speed       = 0;
        targetSpeed.direction   = 0;
        RTE_SC_SPEED_set(&SO_TARGETSPEED_signal, targetSpeed);
    }

    targetSpeed     = RTE_SC_SPEED_get(&SO_TARGETSPEED_signal);
    
    SC_SPEED_data_t controlSpeed    = SC_SPEED_INIT_DATA;
    controlSpeed    = RTE_SC_SPEED_get(&SO_CONTROLSPEED_signal);
 
    SC_TIMEARRAY_data_t encData    = SC_TIMEARRAY_INIT_DATA;
    SC_TIMEARRAY__enterCriticalRegion();
    encData = arrTimer;  // copy entire struct atomically and leave critical section
    SC_TIMEARRAY__leaveCriticalRegion();

    //LOGIC
    
    //Send tbis logic in pullport()
    uint8_t  lastEntry = (encData.idx + MAX_ARRAX_ENCODER - 1) % MAX_ARRAX_ENCODER;
    uint32_t lastTime  = encData.array[lastEntry].timestamp;
    uint16_t rpm       = 0;

    if((DWT->CYCCNT - lastTime) <= 2400000UL)
    {
        uint8_t  found = 0;
        uint32_t first = 0;
        uint32_t last  = 0;

        for(uint8_t i = 0; i < MAX_ARRAX_ENCODER && found < 5; i++)
        {
            // go backwards from newest
            uint8_t pos = (encData.idx + MAX_ARRAX_ENCODER - 1 - i) % MAX_ARRAX_ENCODER;
            if(encData.array[pos].edge == RISING)
            {
                last  = (found == 0) ? encData.array[pos].timestamp : last;
                first = encData.array[pos].timestamp;  // always update, last found = oldest
                found++;
            }
        }
        uint32_t period = last - first;
        if(found >= 5 && period > 0){
            // All 5 edges should span at most 2-3 seconds at minimum RPM
            // At 50 RPM minimum: 2 rotations = 2.4 seconds = 57,600,000 cycles
            if(period < 57600000UL) {
                rpm = (uint32_t)(2880000000UL / period);
            }
            rpm = rpm > MAX_RPM ? MAX_RPM : rpm;
        }     
    }
    
    SC_SPEED_data_t currentSpeed    = SC_SPEED_INIT_DATA;
    currentSpeed    = RTE_SC_SPEED_get(&SO_CURRENTSPEED_signal);
    
    currentSpeed.speed = rpm;
    currentSpeed.direction = targetSpeed.direction;
    
    
    //Closed loop control logic

    /* dt in seconds (adjust divisor to your cycleTime units: ms -> 1000.0f, us -> 1e6f) */
    float dt = (float)cycleTime / 1000.0f;

    float Kp = 0.6f;     // start here, tune
    float Ki = 2.0f;     // 1/s
    float Kd = 0.01f;    // s

    float error = (float)(targetSpeed.speed - currentSpeed.speed);

    static float integral  = 0.0f;
    static float prevError = 0.0f;
    /* derivative on error (consider derivative-on-measurement to avoid setpoint kicks) */
    float derivative = (error - prevError) / dt;
    prevError = error;

    /* tentative output */
    float output = Kp * error + Ki * integral + Kd * derivative;

    /* --- conditional integration (anti-windup): only integrate if not saturating --- */    
    if (output > 0.0f && output < (float)MAX_RPM) {
        integral += error * dt;
    }
    /* recompute with updated integral */
    output = Kp * error + Ki * integral + Kd * derivative;

    /* clamp */
    if (output < 0.0f)              output = 0.0f;
    if (output > (float)MAX_RPM)    output = (float)MAX_RPM;

    if (targetSpeed.speed == 0) {
        integral  = 0.0f;
        prevError = 0.0f;
        output    = 0.0f;
    }

    controlSpeed.speed     = (uint16_t)output;
    controlSpeed.direction = targetSpeed.direction;
    
    RTE_SC_SPEED_set(&SO_CURRENTSPEED_signal, currentSpeed);
    
#if EGAS_SERIAL_STREAM
    LOG_D("T:%d C:%d E:%d\n", targetSpeed.speed*targetSpeed.direction, currentSpeed.speed*currentSpeed.direction, (targetSpeed.speed*targetSpeed.direction-currentSpeed.speed*currentSpeed.direction));
#endif
    
    //OUTPUT
    RTE_SC_SPEED_set(&SO_CONTROLSPEED_signal, controlSpeed);
    RTE_SC_SPEED_set(&SO_TARGETSPEED_signal, targetSpeed);
    RTE_SC_SPEED_pushPort(&SO_CONTROLSPEED_signal);

    //Measure cyclic time of runnable
    Run3_Write(0);
    CancelAlarm(Alarm_control);
    /* USER CODE END EGAS_controlEngine_run */
}

/*
 * component: swc_eGas
 * cycletime: 100
 * description: Runnable
 * events: 
 * name: EGAS_hmi_run
 * shortname: hmi
 * signalIN: so_targetSpeed|so_currentSpeed
 * signalOUT: so_display
 * task: tsk_hmi
 */
void EGAS_hmi_run(RTE_event ev, uint32_t cycleTime){
	
	/* USER CODE START EGAS_hmi_run */

	//Note: 
	//The parameters identify the activation source, which can either be an event (onData, onError) 
	//or a cyclic activation. One of the values will be 0, idicating that this event has not been fired.
	//The other must have a none 0 value.
	
    //INPUT
    //Measure cyclic time of runnable
    Run4_Write(1);
    WD_Alive(3);
        
    SC_SPEED_data_t targetSpeed = SC_SPEED_INIT_DATA;
    SC_SPEED_data_t currentSpeed = SC_SPEED_INIT_DATA;
    SC_JOYSTICK_data_t joystick = SC_JOYSTICK_INIT_DATA;
    
    //Combined signal with all the display values.
    SC_DISPLAY_data_t output = SC_DISPLAY_INIT_DATA;

    
    if(RTE_SIGNALSTATUS_VALID == RTE_SC_JOYSTICK_getStatus(&SO_JOYSTICK_signal)){
        joystick        = RTE_SC_JOYSTICK_get(&SO_JOYSTICK_signal);
    }
    if(RTE_SIGNALSTATUS_VALID == RTE_SC_SPEED_getStatus(&SO_TARGETSPEED_signal)){
        targetSpeed     = RTE_SC_SPEED_get(&SO_TARGETSPEED_signal);
    }
    if(RTE_SIGNALSTATUS_VALID == RTE_SC_SPEED_getStatus(&SO_CURRENTSPEED_signal)){
        currentSpeed    = RTE_SC_SPEED_get(&SO_CURRENTSPEED_signal);
    }
    
    output          = RTE_SC_DISPLAY_get(&SO_DISPLAY_signal);
    
    
    //LOGIC
    output.targetSpeed      = targetSpeed.speed;
    output.targetDirection  = targetSpeed.direction;
    output.currentSpeed     = currentSpeed.speed;
    output.currentDirection = currentSpeed.direction;   
    output.joystick         = joystick.x;
    //output.pixelX = output.pixelX > 127 ? 0 : output.pixelX++; 
    output.pixelX++; 
    
    //OUTPUT
    RTE_SC_DISPLAY_set(&SO_DISPLAY_signal, output);
    RTE_SC_DISPLAY_pushPort(&SO_DISPLAY_signal);
    
    //Measure cyclic time of runnable
    Run4_Write(0);
    CancelAlarm(Alarm_hmi);
    /* USER CODE END EGAS_hmi_run */
}

